void mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (c->stack == NULL) {
    return;
  }

  mrb_value *sp = c->stack + c->stack_size;
  mrb_value *base = c->stack + c->stack_base;

  while (sp > base) {
    mrb_value *v = sp - 1;
    if (!mrb_immediate_p(*v)) {
      mrb_gc_mark(mrb, *v);
    }
    sp--;
  }
}
